      type: "CLOSE_MODAL";
    }
  | {
      type: "CLICK_INTRO";
    }
  | {
      type: "CLICK_SOLUTION";
    }
>({
  initial: "idle",
  states: {
    idle: {
      on: {
        CLICK_INTRO: "introModalOpen",
        CLICK_SOLUTION: "solutionModalOpen",
      },
    },
    introModalOpen: {
      on: {
        CLOSE_MODAL: "idle",
      },
    },
    solutionModalOpen: {
      on: {
        CLOSE_MODAL: "idle",
      },
    },
  },
});

