            fontWeight="bold"
            letterSpacing="tight"
          >
            XState Tutorials
          </Text>
        </HStack>
        <HStack spacing="10">
          <HStack spacing="4" bgColor="gray.100" rounded="full" pr="5">
            <Text
              bgColor="gray.800"
              rounded="full"
              h="9"
              w="9"
              color="white"
              display="flex"
              alignItems="center"
              justifyContent="center"
            >
              #{tutorial.number}
            </Text>
            <Text
              color="gray.800"
              letterSpacing="tight"
              fontWeight="bold"
              fontSize="lg"
            >
              {tutorial.title}
            </Text>
          </HStack>
          <ButtonGroup>
            <Button
              size="sm"
              colorScheme="blue"
              onClick={() => send("CLICK_INTRO")}
            >
              Intro
