                    <MenuItem as="a">
                      <HStack spacing="3">
                        <Text fontSize="sm" letterSpacing="tight">
                          #{index + 1} - <Text as="span">{tutorial.title}</Text>
                        </Text>
                      </HStack>
                    </MenuItem>
                  </Link>
                );
              })}
            </MenuList>
          </Menu>
        </HStack>
      </Box>
      <Box
        h="calc(100vh - 4rem)"
        display="flex"
        flexDir="column"
        alignItems="stretch"
        justifyContent="stretch"
        w="full"
      >
        <Sandpack
          template="react-ts"
          files={{
            ...tutorial.files,
            "/package.json": {
              code: PACKAGE_JSON_CODE,
              hidden: true,
            },
            "/index.tsx": {
              code: INDEX_PAGE_CODE,
